import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# CUDA kernel: straightforward element‑wise max‑pool 2D (fp16 I/O)
# ----------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void maxpool2d_fp16_kernel(
    const __half* __restrict__ input,
    __half* __restrict__ output,
    int batch,
    int channels,
    int in_h, int in_w,
    int out_h, int out_w,
    int k_h, int k_w,
    int s_h, int s_w,
    int p_h, int p_w,
    int d_h, int d_w)
{
    // global thread index over all output elements
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch * channels * out_h * out_w;
    if (idx >= total) return;

    // decode indices
    int w = idx % out_w;
    int tmp = idx / out_w;
    int h = tmp % out_h;
    tmp = tmp / out_h;
    int c = tmp % channels;
    int n = tmp / channels;

    // compute start position in the input tensor for this output element
    int in_y0 = h * s_h - p_h;
    int in_x0 = w * s_w - p_w;

    // initialize max with smallest fp16 value (approx -inf)
    float max_val = -65504.0f;   // -max finite half

    // iterate over kernel window
    for (int ky = 0; ky < k_h; ++ky) {
        int iy = in_y0 + ky * d_h;
        if (iy < 0 || iy >= in_h) continue;
        for (int kx = 0; kx < k_w; ++kx) {
            int ix = in_x0 + kx * d_w;
            if (ix < 0 || ix >= in_w) continue;
            // linear index into input: ((n*channels + c)*in_h + iy)*in_w + ix
            int in_idx = ((n * channels + c) * in_h + iy) * in_w + ix;
            float v = __half2float(input[in_idx]);
            if (v > max_val) max_val = v;
        }
    }

    // write result as half
    int out_idx = ((n * channels + c) * out_h + h) * out_w + w;
    output[out_idx] = __float2half(max_val);
}

// ----------------------------------------------------------------------
// Wrapper callable from Python
// ----------------------------------------------------------------------
torch::Tensor maxpool2d_cuda(
    torch::Tensor input,
    int k_h, int k_w,
    int s_h, int s_w,
    int p_h, int p_w,
    int d_h, int d_w)
{
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kFloat16, "input must be fp16");
    input = input.contiguous();

    const int batch   = input.size(0);
    const int channels= input.size(1);
    const int in_h    = input.size(2);
    const int in_w    = input.size(3);

    // output dimensions following torch.nn.MaxPool2d formula
    const int out_h = std::floor( (in_h + 2 * p_h - d_h * (k_h - 1) - 1) / float(s_h) ) + 1;
    const int out_w = std::floor( (in_w + 2 * p_w - d_w * (k_w - 1) - 1) / float(s_w) ) + 1;

    auto output = torch::empty({batch, channels, out_h, out_w}, input.options());

    const int total = batch * channels * out_h * out_w;
    const int threads = 256;
    const int blocks = (total + threads - 1) / threads;

    maxpool2d_fp16_kernel<<<blocks, threads>>>(
        reinterpret_cast<const __half*>(input.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(output.data_ptr<at::Half>()),
        batch, channels,
        in_h, in_w,
        out_h, out_w,
        k_h, k_w,
        s_h, s_w,
        p_h, p_w,
        d_h, d_w);

    return output;
}
