        super().__init__()
        self.k = kernel_size
        self.s = stride
        self.p = padding
        self.d = dilation

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Preserve original dtype/device
        orig_dtype = x.dtype
        orig_device = x.device

