            x_fp16,
            self.k, self.k,          # kernel_h, kernel_w
            self.s, self.s,          # stride_h, stride_w
            self.p, self.p,          # pad_h, pad_w
            self.d, self.d)          # dilation_h, dilation_w

        return y_fp16.to(dtype=orig_dtype)

